// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        BankStub helper = new BankStub();

        vm.deal(address(helper), 1 ether);

        helper.callAirDrop(address(c));

        uint bal = c.tokenBalance(address(helper));

        assertTrue(bal == 20);
    }
}

contract BankStub {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function callAirDrop(address caddr) external {
        ModifierEntrancy(caddr).airDrop();
    }
}
